import copy
import json
import os

from utils import getLogger

logger = getLogger(os.path.splitext(os.path.basename(__file__))[0])


def parse_r(input_text):
    lines = input_text.strip().split("\n")
    data_types = []

    for line in lines:
        line = line.strip()
        if line.startswith("data:"):
            data_content = line[5:]  # 移除"data:"前缀

            try:
                # 解析JSON数据
                if data_content.strip():  # 确保不是空字符串
                    data_json = json.loads(data_content)
                    # 提取type字段
                    if "type" in data_json:
                        data_types.append(data_json["type"])
                    elif "result" in data_json:
                        data_types.append(data_json["result"])
            except json.JSONDecodeError:
                # 跳过无法解析的JSON
                print(f"无法解析的JSON: {data_content}")
                pass
    types = []
    for t in data_types:
        if t == "url_fetch" or not types or types[-1] != t:
            types.append(t)
    return types


def parse_rs(sses):
    return [parse_r(sse) for sse in sses]


