def verify_card(card, min_depth=4):
    # 验证卡片内容
    outlines = card.get("outlines", {})
    root_node = outlines.get("root_node", {})

    errors = []

    def check_node(node, current_depth=0):
        """递归检查节点深度"""
        children = node.get("children", [])

        # 如果没有子节点，这是一个叶子节点
        if not children:
            if current_depth < min_depth:
                text = node.get("text", "未知节点")
                errors.append(f"节点（{text}）深度为{current_depth}，< {min_depth}")
        else:
            # 递归检查子节点
            for child in children:
                check_node(child, current_depth + 1)

    # 从根节点开始检查
    check_node(root_node, 0)

    # 如果没有错误，则通过验证
    is_valid = len(errors) == 0

    return is_valid, errors


